BEGIN
 SELECT payload INTO v_payload FROM public.wantiss_cms_content WHERE content_key='goodies.content' AND locale='en' AND status='published' ORDER BY version DESC LIMIT 1 FOR UPDATE;
 IF v_payload IS NULL THEN RAISE EXCEPTION 'Published Goodies CMS content not found'; END IF;
 v_old:=coalesce(v_payload->'labels','[]'::jsonb);
 SELECT coalesce(jsonb_agg(o.value || CASE WHEN n.value IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('t',coalesce(n.value->'t','{}'::jsonb)||coalesce(o.value->'t','{}'::jsonb)) END ORDER BY o.ord),'[]'::jsonb)
 INTO v_labels FROM jsonb_array_elements(v_old) with ordinality o(value,ord)
 LEFT JOIN jsonb_array_elements(v_new) n(value) ON n.value->>'id'=o.value->>'id';
 SELECT v_labels||coalesce(jsonb_agg(n.value),'[]'::jsonb) INTO v_labels FROM jsonb_array_elements(v_new) n(value)
 WHERE NOT EXISTS(select 1 from jsonb_array_elements(v_old) o(value) where o.value->>'id'=n.value->>'id');
 UPDATE public.wantiss_cms_content SET payload=jsonb_set(v_payload,'{labels}',v_labels,true),updated_at=now()
 WHERE id=(select id from public.wantiss_cms_content where content_key='goodies.content' and locale='en' and status='published' order by version desc limit 1);
END $$;
